import { act, renderHook } from '@testing-library/react-hooks';
import useData from '../useData';

describe('hook', () => {
  test('useData', () => {
    const { result } = renderHook(() => useData({ id: 1 }));

    act(() => {
      result.current.setData({});
    });

    expect(result.current.data).toStrictEqual({});
  });
});
